{
    "select_freshness": {
        "description": "Check the freshness of evidence sources for today's data.",
        "python_tools": [],
        "sql_templates": [
            {
                "name": "Check Index Freshness",
                "template": "SELECT index_symbol, MAX(trade_date) AS last_date FROM market.index_eod GROUP BY index_symbol;"
            },
            {
                "name": "Check Equity Freshness",
                "template": "SELECT symbol, MAX(trade_date) AS last_date FROM market.equity_eod GROUP BY symbol;"
            },
            {
                "name": "Check Stage Snapshots Freshness",
                "template": "SELECT sector, MAX(snapshot_date) AS last_snapshot FROM scores.stage_snapshots GROUP BY sector;"
            }
        ]
    }
}
